import { readFile } from 'node:fs/promises'
import { getMigrations } from 'better-auth/db/migration'
import { accountRuntime } from '@/lib/account-runtime'

const service = accountRuntime
if (!service) throw new Error('AccountConfigurationRequired')
try {
    const migration = await getMigrations(service.auth.options)
    // Only dedicated HAWConnect-prefixed tables are generated by this configuration.
    await migration.runMigrations()
    await service.pool.query(
        await readFile(new URL('./sync.sql', import.meta.url), 'utf8')
    )
    console.info('HAWConnect account migrations complete')
} finally {
    await service.pool.end()
}
